{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.ras_sales_data as WITH inventory as ( select case when i.brand IN (\"RBPL- MOODY\",\"MOODY\") THEN \"MOODY\" ELSE \"RAS\" END as Brand_name , i.sku , i.product_name from `MAPLEMONK.ras_inventory_fact_items` i ), sku_master as ( select sm.sku , sm.brand from `MAPLEMONK.ras_sku_master` sm ) select coalesce(i.Brand_name, case when sm.brand in (\"Moody Store\",\"Moody\",\"Moody Website\",\"B26779\") then \"MOODY\" else (case when sm.brand in (\"RAS LUXURY OILS\",\"RAS Luxury Oils India\",\"RAS Luxury Skincare\",\"RAS Luxury Oils\",\"RBPL - RAS\",\"RAS\",\"24KGOLDYOUDUO\",\"B12759\") then \"RAS\" else (case when sm.brand in(\"RBPL - RAS\") then \"RAS\" else \"MOODY\" end) end) end ) Brand_name, s.* from `MAPLEMONK.ras_sales_consolidated` s left join inventory i on s.sku=i.sku and s.product_name = i.product_name left join sku_master sm on sm.sku = s.sku; create or replace table maplemonk.ras_po_tracker as WITH grn_details as ( select g._id , g.grnId , g.updated_at as grn_updated_date , g.po , cast(json_extract_scalar(skus,\'$.productName\') as string) as product_name , cast(json_extract_scalar(skus,\'$.taxPerItem\') as float64) as tax_per_item , cast(json_extract_scalar(skus,\'$.OriginalOrderedQuantity\') as int64) as original_order_quantity ,cast(json_extract_scalar(skus,\'$.totalReturnQuantity\') as int64) as total_returned_quantity , cast(json_extract_scalar(skus,\'$.unitTotal\') as float64) as total_units , cast(json_extract_scalar(skus,\'$.basePrice\') as float64) as base_price , cast(json_extract_scalar(skus,\'$.mrp\') as float64) as mrp , cast(json_extract_scalar(skus,\'$.taxRate\') as float64) as tax_rate , cast(json_extract_scalar(skus,\'$.netAmount\') as float64) as net_Amount , cast(json_extract_scalar(skus,\'$.batchCode\') as string) as batchCode from ( select * , cast(cast(po_number as int64) as string) as po , ROW_NUMBER() OVER (PARTITION BY cast(cast(po_number as int64) as string) ORDER BY updated_at DESC) as rw from `MAPLEMONK.edgistify_get_grn_details` ) g left join unnest(g.skus) as skus where rw = 1 ), po_details as ( select p.isActive , p.po_number , p.orderStatus , p.poCreatedOn , p.vendor_name , p.warehouse_name , p.shipping_partner , p.poReferenceNumber , p.orderStatusReadable , p.estimated_delivery_date from ( select * , ROW_NUMBER() OVER (PARTITION BY po_number order by pocreatedon desc) as rw from `MAPLEMONK.edgistify_get_po_list` ) p where rw = 1 ) select po.isActive , po.po_number , po.orderStatus , po.poCreatedOn , po.estimated_delivery_date , po.vendor_name , po.warehouse_name , po.shipping_partner , po.poReferenceNumber , po.orderStatusReadable , g.grn_updated_date , g.grnId , g.product_name , g.original_order_quantity , g.total_returned_quantity , g.total_units , g.batchCode , g.mrp , g.tax_rate , g.tax_per_item , g.net_Amount from po_details po left join grn_details g on g.po = po.po_number;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            